pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testRegression_property() public {
        // Deploy with a separate operator (address(1)) that is not owner
        address operator = address(1);
        // Set up the operator address in the contract (since constructor set it to this, we change it)
        // Actually constructor sets operator to address(this), we need to change it to address(1)
        // The owner (this) calls setOperator
        c.setOperator(operator);
        // Now operator calls depositAndStake - succeeds in both
        vm.prank(operator);
        c.depositAndStake(0);
        // Now operator tries to withdrawAndUnwrap - should succeed in reference (operator matches)
        // but fail in mutant because owner() returns address(0) and operator != owner (address(0))
        bool ok;
        try c.withdrawAndUnwrap(0, false, address(0)) { ok = true; }
        catch { ok = false; }
        assertTrue(ok);
    }
}

