// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testRegression_property() public {
        // Set operator to address(this) so depositAndStake can be called
        c.setOperator(address(this));
        // No shutdown: poolInfo returns shutdown=false by default for pId=0
        // We call depositAndStake(0) to exercise the isCvxShutdown check.
        // Reference: isCvxShutdown returns false => enters the if block and does safeIncreaseAllowance/deposit (with amount=0)
        // Buggy: isCvxShutdown returns true => skips the block, function succeeds.
        // However, the difference must be observable. Since both succeed with amount=0, we need another approach:
        // Actually, if isCvxShutdown returns false, it will try safeIncreaseAllowance (which requires token allowance 0 to work for zero? It will just approve + deposit(0) – both should succeed).
        // If isCvxShutdown returns true, it skips everything and also succeeds. So no divergence for amount=0.
        // To force a revert on buggy version, we need to make the reference succeed but the buggy revert.
        // But the buggy version's true prevents any action (no revert). So both succeed.
        // Wait, the problem says: they differ in that isCvxShutdown returns different values, but both calls complete (no revert). So we need to observe a state change difference.
        // The only state change after depositAndStake(0) in the reference is that it does safeIncreaseAllowance and deposit(0). The buggy does nothing.
        // For amount=0, safeIncreaseAllowance and deposit may have no effect? Actually safeIncreaseAllowance(booster,0) requires approval of 0, call to approve(0). deposit(0) might revert if pool doesn't accept zero? But assume it doesn't.
        // To make observable: we can check clpToken.allowance to booster after call.
        // Reference: allowance might be 0+0=0, deposit(0) doesn't change balance.
        // Buggy: allowance stays 0.
        // So no difference.
        // Better: use a non-zero amount that triggers transferFrom? No, we need the isCvxShutdown to control branching. The only divergence is the boolean itself.
        // We can directly call isCvxShutdown() after setup and assert it returns false on reference, true on buggy.
        // But the test must call depositAndStake as entry.
        // The instruction: "Driven through the public/external entry depositAndStake(uint256), P and M differ in this way: a call isCvxShutdown(args) that completes ... but returns different values."
        // So we can call depositAndStake with some argument, then call isCvxShutdown() and assert its return value.
        // But depositAndStake does not change the pool shutdown status, so isCvxShutdown returns the same before and after.
        // So prior to depositAndStake, the shutdown status is known: it's false (default). We can just call depositAndStake(0) then check isCvxShutdown() reference returns false, buggy returns true.
        // That satisfies the requirement: the call sequence includes depositAndStake, and the final assertion is on c.isCvxShutdown(). Reference holds (false), bug breaks (true).
        // Let's implement that.
        c.depositAndStake(0);
        assertTrue(!c.isCvxShutdown()); // In reference, isCvxShutdown returns false; in mutant, returns true, so this assertion fails.
    }
}

