pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testRegression_property() public {
        // Simulate that the CVX pool is not shutdown by setting the pId to a non-existent one
        // The booster is the zero address, so any call to booster.poolInfo will revert
        // But we can still test the function call by ensuring allowance is non-zero
        // Since clpToken is at address(0), safeIncreaseAllowance will revert due to non-contract
        // Instead, set up an operator that can call depositAndStake
        address operator = address(0x1234);
        // Set operator using the setOperator function (onlyOwner)
        c.setOperator(operator);
        // Approve the booster to spend clpToken (booster is address(0), so this is a call to address(0))
        // We need to avoid revert on non-contract; but we can't mock
        vm.prank(operator);
        try c.depositAndStake(0) {
            // Success means the reference is correct here
        } catch {
            revert("Test failed: depositAndStake should not revert");
        }
        // Now the property: after a successful call (reference), we assert that operator can call again
        // But due to the bug, the mutant would revert; we can't directly observe revert with assertTrue
        // Instead, use another approach: assert that isCvxShutdown returns false
        bool shutdown = c.isCvxShutdown();
        // Reference: shutdown == false, mutant: shutdown == true
        // We can assert that shutdown is false
        assertTrue(!shutdown, "isCvxShutdown should return false for non-shutdown pool");
    }
}

