pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testRegression_property() public {
        // Deploy a minimal ERC20 token as clpToken; using address(0) is invalid, so we create a mock
        address clpToken = address(new ERC20Mock("CLP", "CLP", 18));
        C c2 = new C(address(this), IERC20(clpToken), ICVXBooster(address(0)), new address, 0);
        // Fund clpToken to c2
        ERC20Mock(clpToken).mint(address(this), 1000);
        ERC20Mock(clpToken).approve(address(c2), 1000);
        vm.prank(address(this));
        ERC20Mock(clpToken).transfer(address(c2), 100);
        // Set up booster mock to avoid revert; but we need a minimal ICVXBooster
        // For simplicity, we use a pre-existing mock pattern; here we deploy a tiny helper
        address booster = address(new BoosterMock());
        C c = new C(address(this), IERC20(clpToken), ICVXBooster(booster), new address, 0);
        // Transfer CLP to c
        ERC20Mock(clpToken).transfer(address(c), 100);
        // Set poolInfo to not shutdown (shutdown=false)
        BoosterMock(booster).setPoolInfo(c.cvxPoolInfo.pId(), address(0), address(0), address(0), address(0), false);
        // Call depositAndStake(100) as operator
        vm.prank(address(this));
        c.depositAndStake(100);
        // Now withdrawAndUnwrap(200, false, address(1))
        vm.prank(address(this));
        c.withdrawAndUnwrap(200, false, address(1));
        // Assert: address(1) should have 200 CLP in reference (but bug skips withdrawal)
        assertTrue(ERC20Mock(clpToken).balanceOf(address(1)) >= 200);
    }
}

contract ERC20Mock {
    string public name;
    string public symbol;
    uint8 public decimals;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    constructor(string memory _name, string memory _symbol, uint8 _decimals) { name = _name; symbol = _symbol; decimals = _decimals; }
    function transfer(address to, uint256 amount) external returns (bool) { balanceOf[msg.sender] -= amount; balanceOf[to] += amount; return true; }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) { allowance[from][msg.sender] -= amount; balanceOf[from] -= amount; balanceOf[to] += amount; return true; }
    function approve(address spender, uint256 amount) external returns (bool) { allowance[msg.sender][spender] = amount; return true; }
    function mint(address to, uint256 amount) external { balanceOf[to] += amount; }
}

contract BoosterMock {
    struct PoolInfo { address lptoken; address token; address gauge; address crvRewards; address stash; bool shutdown; }
    mapping(uint256 => PoolInfo) public poolInfo;
    function setPoolInfo(uint256 pid, address lptoken, address token, address gauge, address crvRewards, address stash, bool shutdown) external {
        poolInfo[pid] = PoolInfo(lptoken, token, gauge, crvRewards, stash, shutdown);
    }
}
